const cache=new Map(),lifetime=30*60*1000;
const wears={'Factory New':'Recién fabricado','Minimal Wear':'Casi nuevo','Field-Tested':'Algo desgastado','Well-Worn':'Bastante desgastado','Battle-Scarred':'Deplorable'};
export function priceCacheKey(id,wear='',variant='normal'){return JSON.stringify([id,wear,variant])}
export function cardPriceLabel(quote){if(Number.isSafeInteger(quote?.price)&&quote.price>=0)return new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(quote.price/100);return quote?.status==='phase_unavailable'?'Sin fase':quote?.status==='no_listing'?'Sin ofertas':'—'}
export function createCardPrices(root){
 let observer,queue=new Set(),visible=new Set(),flushTimer=null,running=false,generation=0;
 const keyFor=e=>priceCacheKey(e.dataset.priceSkin,e.dataset.priceWear,e.dataset.priceVariant);
 function fill(e,row){if(!e.isConnected)return;if(e.classList.contains('steam-quote')){const q=row.providers.find(p=>p.provider==='steam');e.textContent='Steam '+cardPriceLabel(q);e.dataset.priceLoaded='true';e.title=q?.source_updated_at?'Steam · origen '+new Date(q.source_updated_at).toLocaleString('es-EC'):'Sin cotización disponible';e.classList.toggle('price-stale',!!q?.warning||!!q?.stale);return}const variant=row.variant==='stattrak'?'StatTrak™':row.variant==='souvenir'?'Souvenir':'Normal';e.querySelector('.card-price-condition').textContent=variant+' · USD';const body=e.querySelector('.card-wear-prices');body.replaceChildren();
  for(const condition of row.conditions||[row]){const tr=document.createElement('tr'),label=document.createElement('th');label.scope='row';label.textContent=wears[condition.wear]||'Sin desgaste';tr.append(label);for(const provider of ['steam','csfloat']){const quote=condition.providers.find(p=>p.provider===provider),td=document.createElement('td');td.textContent=cardPriceLabel(quote);td.classList.toggle('price-missing',quote?.price==null);td.classList.toggle('price-stale',!!quote?.warning||!!quote?.stale);const stamp=quote?.source_updated_at&&new Date(quote.source_updated_at);td.title=stamp&&Number.isFinite(stamp.getTime())?'Origen: '+stamp.toLocaleString('es-EC')+(quote.warning?' · Dato anterior':''):'Sin cotización disponible';tr.append(td)}body.append(tr)}e.dataset.priceLoaded='true';e.setAttribute('aria-label','Precios por desgaste. '+variant);
 }
 function schedule(e){const entry=cache.get(keyFor(e));if(entry){fill(e,entry.row);if(Date.now()<entry.expires)return}queue.add(e);clearTimeout(flushTimer);flushTimer=setTimeout(flush,180)}
 async function flush(){if(running||document.hidden||root.hidden)return;const entries=[...queue].filter(e=>e.isConnected&&visible.has(e));queue.clear();if(!entries.length)return;const first=entries[0],wear=first.dataset.priceWear,variant=first.dataset.priceVariant,group=entries.filter(e=>e.dataset.priceWear===wear&&e.dataset.priceVariant===variant).slice(0,36);for(const e of entries)if(!group.includes(e))queue.add(e);running=true;const version=generation;
  try{const response=await fetch(LOADOUT_CLOUD.url+'/functions/v1/market-prices',{method:'POST',headers:{'Content-Type':'application/json',apikey:LOADOUT_CLOUD.publishableKey},body:JSON.stringify({skins:[...new Set(group.map(e=>e.dataset.priceSkin))],wear,variant,all_wears:!wear})});if(!response.ok)throw Error();const value=await response.json();if(!Array.isArray(value.items))throw Error();
   for(const e of group){const conditions=value.items.filter(r=>r.skin===e.dataset.priceSkin),row=conditions.length?{...conditions[0],conditions}:null;if(row){cache.set(keyFor(e),{row,expires:Date.now()+lifetime});fill(e,row)}else if(!value.retry_after){const old=cache.get(keyFor(e));if(old)fill(e,old.row);else{if(e.classList.contains('steam-quote'))e.textContent='Steam —';else{e.querySelector('.card-price-condition').textContent='Sin cotización disponible';e.querySelector('.card-wear-prices').textContent='No disponible ahora'}}}}
   if(value.retry_after&&version===generation)setTimeout(()=>{for(const e of group)if(e.isConnected&&visible.has(e))schedule(e)},Math.min(30,Number(value.retry_after)+1)*1000);
  }catch{for(const e of group){const old=cache.get(keyFor(e));if(old)fill(e,{...old.row,providers:old.row.providers.map(p=>({...p,warning:'unavailable'}))});else if(e.isConnected){if(e.classList.contains('steam-quote'))e.textContent='Steam —';else{e.querySelector('.card-wear-prices').textContent='No disponible ahora';e.querySelector('.card-price-condition').textContent='Precio no disponible';}}}}
  finally{running=false;if(queue.size)flushTimer=setTimeout(flush,250)}
 }
 const interval=setInterval(()=>{if(!document.hidden&&!root.hidden)for(const e of visible)schedule(e)},60000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!root.hidden)for(const e of visible)schedule(e)});
 return{observe(){generation++;observer?.disconnect();queue.clear();visible.clear();observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){visible.add(entry.target);schedule(entry.target)}else visible.delete(entry.target)}},{rootMargin:'120px'});root.querySelectorAll('.card-market-prices,.steam-quote[data-price-skin]').forEach(e=>observer.observe(e))},dispose(){observer?.disconnect();clearInterval(interval);clearTimeout(flushTimer);queue.clear();visible.clear()}};
}
